27	// ─── Proxy environment variables ─────────────────────────────────────────────
28	
29	/**
30	 * Names of the proxy environment variables Konnect sync manages.
31	 * On first sync, values are auto-filled from the control plane's `proxy_urls`
32	 * when available; otherwise created as empty strings for manual entry.
33	 *
34	 * - `proxy_host`: host (with port when non-standard), used in http/https/ws/wss URLs.
35	 * - `grpc_proxy_host`: host:port, used in grpc:// URLs.
36	 * - `grpcs_proxy_host`: host:port, used in grpcs:// URLs.
37	 */
38	export const KONNECT_PROXY_VAR_NAMES = ['proxy_host', 'grpc_proxy_host', 'grpcs_proxy_host'] as const;
39	
40	const HTTP_LIKE_PROTOCOLS = new Set(['http', 'https', 'ws', 'wss']);
41	const GRPC_PROTOCOL = 'grpc';
42	const GRPCS_PROTOCOL = 'grpcs';
43	
44	/** Default ports per protocol — used to suppress redundant port numbers in the output. */
45	const DEFAULT_PORTS: Record<string, number> = { http: 80, ws: 80, https: 443, wss: 443 };
46	
47	/** Returns `host` for standard ports, `host:port` for non-standard ones. */
48	function formatHttpLikeHost(host: string, port: number, protocol: string): string {
49	  const defaultPort = DEFAULT_PORTS[protocol];
50	  return defaultPort !== undefined && port === defaultPort ? host : `${host}:${port}`;
51	}
52	
53	/**
54	 * Derives default values for the proxy environment variables from a control
55	 * plane's `proxy_urls` array. Returns a partial map of var-name → value;
56	 * omitted keys mean no matching entry was found.
57	 *
58	 * - `proxy_host`       ← first http/https/ws/wss entry → host[:port] (port omitted if standard)
59	 * - `grpc_proxy_host`  ← first grpc entry → host:port
60	 * - `grpcs_proxy_host` ← first grpcs entry → host:port
61	 */
62	export function deriveProxyVarDefaults(
63	  proxyUrls: KonnectProxyUrl[] | null | undefined,
64	): Partial<Record<(typeof KONNECT_PROXY_VAR_NAMES)[number], string>> {
65	  const defaults: Partial<Record<(typeof KONNECT_PROXY_VAR_NAMES)[number], string>> = {};
66	  if (!proxyUrls?.length) {
67	    return defaults;
68	  }
69	
70	  for (const entry of proxyUrls) {
71	    if (!entry.host) {
72	      continue;
73	    }
74	    const proto = entry.protocol.toLowerCase();
75	    if (!defaults.proxy_host && HTTP_LIKE_PROTOCOLS.has(proto)) {
76	      defaults.proxy_host = formatHttpLikeHost(entry.host, entry.port, proto);
77	    } else if (!defaults.grpc_proxy_host && proto === GRPC_PROTOCOL) {
78	      defaults.grpc_proxy_host = `${entry.host}:${entry.port}`;
79	    } else if (!defaults.grpcs_proxy_host && proto === GRPCS_PROTOCOL) {
80	      defaults.grpcs_proxy_host = `${entry.host}:${entry.port}`;
81	    }
82	  }
83	
84	  return defaults;
85	}
