96	/**
97	 * Converts a Kong regex path string (tilde prefix already stripped) into:
98	 *   - a URL path using Insomnia's colon syntax (`:paramname`), and
99	 *   - a `pathParameters` array the user fills in via the Path Parameters tab.
100	 *
101	 * Named capture groups → `:name` (lowercased).
102	 * Unnamed groups and stray character classes → `:param_1`, `:param_2`, … (shared counter).
103	 * If the regex is too complex to parse cleanly, falls back to `/:path` (replace) or the raw
104	 * regex string with no path parameters (keep).
105	 */
106	export function generatePathPlaceholder(
107	  regexString: string,
108	  fallbackMode: 'keep' | 'replace' = 'replace',
109	): ResolvedPath {
110	  const paramNames: string[] = [];
111	
112	  // Strip starting and ending anchors
113	  let path = regexString.replace(/^\^|\$$/g, '');
114	
115	  // Un-escape standard path characters
116	  path = path.replace(/\\\//g, '/');
117	  path = path.replace(/\\\./g, '.');
118	  path = path.replace(/\/\?$/, '/'); // Optional trailing slash
119	
120	  // Passes must run in this order:
121	  //   1. Named groups  — pattern `(?<name>...)` starts with `(?<`, so it's consumed before pass 2.
122	  //   2. Unnamed groups — matches remaining `(...)` after named groups are gone.
123	  //   3. Stray character classes — matches `[...]` that weren't inside a group.
124	  // Reordering would cause pass 2 to match the inner `(` of a named group before pass 1 can handle it.
125	
126	  // Pass 1 — Named groups: (?<userId>\d+) → :userid
127	  path = path.replace(/\(\?<([a-zA-Z0-9_]+)>[^)]+\)/g, (_, groupName: string) => {
128	    const name = groupName.toLowerCase();
129	    paramNames.push(name);
130	    return `:${name}`;
131	  });
132	
133	  // Passes 2 & 3 share a single param_N counter so the user sees one contiguous sequence
134	  // (:param_1, :param_2, …) rather than two separate ones.
135	  let paramCounter = 1;
136	  // Pass 2 — Unnamed groups: ([0-9]+) → :param_N
137	  path = path.replace(/\([^)]+\)/g, () => {
138	    const name = `param_${paramCounter++}`;
139	    paramNames.push(name);
140	    return `:${name}`;
141	  });
142	  // Pass 3 — Stray character classes: [a-z]+ → :param_N
143	  path = path.replace(/\[[^\]]+\][+*?]?/g, () => {
144	    const name = `param_${paramCounter++}`;
145	    paramNames.push(name);
146	    return `:${name}`;
147	  });
148	
149	  // Validation: Check for leftover regex syntax
150	  const hasLeftoverRegex = /[()[\]*+?\\]/.test(path);
151	  if (hasLeftoverRegex) {
152	    if (fallbackMode === 'keep') { return { path: regexString, pathParameters: [] }; }
153	    return { path: '/:path', pathParameters: [{ name: 'path', value: '' }] };
154	  }
155	
156	  // Ensure it starts with a slash
157	  if (!path.startsWith('/')) {
158	    path = '/' + path;
159	  }
160	
161	  return {
162	    path,
163	    pathParameters: paramNames.map(name => ({ name, value: '' })),
164	  };
165	}
