/**
 * Matches a single Nunjucks-style template pair — a `{{ ... }}` variable
 * expression or a `{% ... %}` block tag. The alternation is non-greedy, so each
 * match ends at the first closing delimiter of its own kind. A tag of the other
 * kind interleaved inside (e.g. `{% %}` within `{{ }}`, or `{{ }}` within
 * `{% %}`) is therefore swallowed as part of the outer expression rather than
 * escaping the strip. `[\s\S]` is used instead of `.` so multi-line expressions
 * are matched too.
 */
const TEMPLATE_PAIR = /\{\{[\s\S]*?\}\}|\{%[\s\S]*?%\}/g;

/**
 * Removes every complete `{{ ... }}` and `{% ... %}` template pair from a string,
 * leaving surrounding text — and any unpaired delimiter with no matching close —
 * intact. Runs to a fixed point so that a pair revealed (or reconstructed) by an
 * earlier removal, a template-injection vector via interleaved delimiters, is
 * also stripped.
 */
function stripTemplates(value: string): string {
  let result = value;
  let previous: string;
  do {
    previous = result;
    result = result.replace(TEMPLATE_PAIR, '');
  } while (result !== previous);
  return result;
}

